		} else {
			w *= loadBoost
		}
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * w
		}
	}

	// Find max FreeKVBlocks for normalization
	maxFreeKV := int64(1)
	for _, snap := range snapshots {
		if snap.FreeKVBlocks > maxFreeKV {
			maxFreeKV = snap.FreeKVBlocks
		}
	}

